import React from 'react';
import Slider from 'react-slick';
import './Works.css';

const Works = () => {
    const settings = {
        dots: true,
        infinite: true,
        speed: 500,
        slidesToShow: 1,
        slidesToScroll: 1,
        arrows: false
    };

    const totalImages = 10; // Total number of images in the folder
    const projectImages = [];

    // Generate image paths
    for (let i = 1; i <= totalImages; i++) {
        const imageName = `${i.toString().padStart(2, '0')}.jpg`; // Assuming images are in JPEG format
        const imagePath = process.env.PUBLIC_URL + `/img/graphicverse/${imageName}`;
        projectImages.push(imagePath);
    }

    return (
        <section id="works">
            <div className="content">
                <div className="text-container">
                    <h1>My Previous Projects</h1>
                </div>
                <div className="carousel-container">
                    <Slider {...settings}>
                        {projectImages.map((image, index) => (
                            <div key={index}>
                                <img src={image} alt={`Project ${index + 1}`} />
                            </div>
                        ))}
                    </Slider>
                </div>
            </div>
        </section>
    );
};

export default Works;
